const updateModifierGroup = `-- name: UpdateModifierGroup :one
UPDATE modifier_groups SET version = version + 1, name_en = $3, name_ne = $4, min_select = $5, max_select = $6
WHERE id = $1 AND version = $2
RETURNING id, version, name_en, name_ne, min_select, max_select
`

type UpdateModifierGroupParams struct {
	ID        uuid.UUID `json:"id"`
	Version   int64     `json:"version"`
	NameEn    string    `json:"name_en"`
	NameNe    string    `json:"name_ne"`
	MinSelect int32     `json:"min_select"`
	MaxSelect int32     `json:"max_select"`
}

func (q *Queries) UpdateModifierGroup(ctx context.Context, arg UpdateModifierGroupParams) (ModifierGroup, error) {
	row := q.db.QueryRow(ctx, updateModifierGroup,
		arg.ID,
		arg.Version,
		arg.NameEn,
		arg.NameNe,
		arg.MinSelect,
		arg.MaxSelect,
	)
	var i ModifierGroup
	err := row.Scan(
		&i.ID,
		&i.Version,
		&i.NameEn,
		&i.NameNe,
		&i.MinSelect,
		&i.MaxSelect,
	)
	return i, err
}
